import re

def verify_access_log(log_path: str, allowed_ips: list[str]) -> list[str]:
    """Return IPs found in log_path that are not in allowed_ips."""
    ip_pattern = re.compile(r'\b(?:\d{1,3}\.){3}\d{1,3}\b')
    unauthorized = set()
    allowed_set = set(allowed_ips)

    with open(log_path, 'r', encoding='utf-8') as f:
        for line in f:
            for ip in ip_pattern.findall(line):
                if ip not in allowed_set:
                    unauthorized.add(ip)

    return list(unauthorized)
```

