    logs = []
    while True:
        ts = datetime.datetime.utcnow().isoformat()
        for c in psutil.net_connections(kind='inet'):
            if c.laddr.ip == host and c.status == 'ESTABLISHED':
                logs.append({'timestamp': ts, 'src': f'{c.raddr.ip}:{c.raddr.port}'})
        time.sleep(interval_s)
        # break condition can be added as needed
    return logs
