import re
from collections import Counter

def _tokenize(s: str) -> list[str]:
    return re.findall(r'\b\w+\b', s.lower())

def classify_document(text: str, categories: list[str]) -> str:
    """Return the category whose name shares the most words with the text."""
    text_words = Counter(_tokenize(text))
    best_cat, best_score = None, -1
    for cat in categories:
        cat_words = _tokenize(cat)
        score = sum(text_words[w] for w in cat_words)
        if score > best_score:
            best_cat, best_score = cat, score
    return best_cat if best_cat is not None else ""
