import os
import stat

def find_writable_files(directory: str) -> list[str]:
    writable = []
    for root, _, files in os.walk(directory):
        for name in files:
            path = os.path.join(root, name)
            try:
                mode = os.stat(path).st_mode
                # Check if file is writable by others or group (potential escalation)
                if mode & (stat.S_IWGRP | stat.S_IWOTH):
                    writable.append(path)
            except OSError:
                continue
    return writable
