from scapy.all import rdpcap, DNSQR, DNSRR
import math
from collections import Counter

def _entropy(s: str) -> float:
    p = Counter(s)
    return -sum((c/len(s))*math.log2(c/len(s)) for c in p.values())

def analyze_dns_traffic(pcap_file: str) -> dict:
    pkts = rdpcap(pcap_file)
    suspicious = {"dga": [], "tunneling": [], "exfiltration": []}
    seen = set()

    for pkt in pkts:
        if not pkt.haslayer(DNSQR):
            continue
        qname = pkt[DNSQR].qname.decode().strip('.')
        if qname in seen:
            continue
        seen.add(qname)

        labels = qname.split('.')
        domain = '.'.join(labels[-2:])          # eTLD+1 approximation
        sub = '.'.join(labels[:-2])

        # DGA: high entropy, long label, many unique queries
        if len(sub) > 12 and _entropy(sub) > 3.5:
            suspicious["dga"].append(qname)

        # Tunneling: many sub‑domains, low entropy, often base64‑like
        if len(labels) > 4 and all(c.isalnum() or c == '-' for c in sub):
            if _entropy(sub) < 2.5:
                suspicious["tunneling"].append(qname)

        # Exfiltration: many queries to same domain with incremental data
        if pkt.haslayer(DNSRR):
            ans = pkt[DNSRR].rrname.decode().strip('.')
            if ans.endswith(domain) and len(ans) - len(domain) > 8:
                suspicious["exfiltration"].append(qname)

    # deduplicate
    for k in suspicious:
        suspicious[k] = list(dict.fromkeys(suspicious[k]))
    return suspicious
```

